<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\ValueObject\UserPersonalApiKeyUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserPersonalApiKeyUserAccessor
{
    private UserPersonalApiKeyUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): UserPersonalApiKeyUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(UserPersonalApiKeyUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = UserPersonalApiKeyUserVO::from($user);
        return $copy;
    }
}
